def register(registry):
    registry.register("sangfor_xdr_alerts", run_alerts)
    registry.register("sangfor_xdr_incidents", run_incidents)
    registry.register("sangfor_xdr_assets", run_assets)
    registry.register("sangfor_xdr_vulns", run_vulns)
    registry.register("sangfor_xdr_whitelists", run_whitelists)
    registry.register("sangfor_xdr_responses", run_responses)
    registry.register("sangfor_xdr_bigscreen_manage", run_bigscreen_manage)
    registry.register("sangfor_xdr_bigscreen", run_bigscreen)
    registry.register("sangfor_xdr_riskassets", run_riskassets)
    registry.register("sangfor_xdr_analysislog", run_analysislog)
    registry.register("sangfor_xdr_soar", run_soar)
    registry.register("sangfor_xdr_orders", run_orders)
    registry.register("sangfor_xdr_orders_manage", run_orders_manage)
    registry.register("sangfor_xdr_vulns_manage", run_vulns_manage)
    registry.register("sangfor_xdr_assets_manage", run_assets_manage)
    registry.register("sangfor_xdr_device", run_device)
    registry.register("sangfor_xdr_siem", run_siem)
